import fs from 'node:fs';
import path from 'node:path';
import { isLegacyProject } from '@hubspot/project-parsing-lib/projects';
import { translateForLocalDev } from '@hubspot/project-parsing-lib/translate';
import { loadConfigByPath } from '../config.js';
import { PRIVATE_APP, PUBLIC_APP } from '../constants.js';
export const HSPROJECT_FILE = 'hsproject.json';
// wrap isLegacyProject because it returns false when platformVersion is undefined,
// but we actually want to treat missing platformVersion as legacy.
export function isLegacyPlatformVersion(platformVersion) {
    if (!platformVersion)
        return true;
    return isLegacyProject(platformVersion);
}
export function findProjectRoot(startPath) {
    let current = path.resolve(startPath);
    for (;;) {
        if (fs.existsSync(path.join(current, HSPROJECT_FILE))) {
            return current;
        }
        const parent = path.dirname(current);
        if (parent === current) {
            throw new Error(`Could not find ${HSPROJECT_FILE} in ${startPath} or any parent directory`);
        }
        current = parent;
    }
}
export function loadProjectConfig(projectDir) {
    const configPath = path.join(projectDir, HSPROJECT_FILE);
    return loadConfigByPath(configPath);
}
// Mirrors: https://git.hubteam.com/HubSpot/hubspot-cli-private/blob/master/commands/project/dev/unifiedFlow.ts
export async function buildUnifiedComponents(projectDir, projectConfig, accountId) {
    if (!projectConfig.platformVersion) {
        throw new Error('platformVersion is required in hsproject.json for unified projects');
    }
    const projectSourceDir = path.resolve(projectDir, projectConfig.srcDir);
    const { intermediateRepresentation } = await translateForLocalDev({
        projectSourceDir,
        platformVersion: projectConfig.platformVersion,
        accountId,
    });
    return {
        components: intermediateRepresentation.intermediateNodesIndexedByUid,
        profileData: intermediateRepresentation.profileData ?? {},
    };
}
export function buildLegacyComponents(projectDir, projectConfig) {
    const srcDir = path.resolve(projectDir, projectConfig.srcDir);
    if (!fs.existsSync(srcDir)) {
        throw new Error(`Source directory not found: ${srcDir}`);
    }
    const components = {};
    const entries = fs.readdirSync(srcDir, { withFileTypes: true });
    for (const entry of entries) {
        if (!entry.isDirectory())
            continue;
        const appDir = path.join(srcDir, entry.name);
        const publicAppPath = path.join(appDir, 'public-app.json');
        const privateAppPath = path.join(appDir, 'app.json');
        if (fs.existsSync(publicAppPath)) {
            components[entry.name] = {
                type: PUBLIC_APP,
                config: loadConfigByPath(publicAppPath),
                path: appDir,
            };
        }
        else if (fs.existsSync(privateAppPath)) {
            components[entry.name] = {
                type: PRIVATE_APP,
                config: loadConfigByPath(privateAppPath),
                path: appDir,
            };
        }
    }
    if (Object.keys(components).length === 0) {
        throw new Error(`No app configurations (app.json or public-app.json) found in ${srcDir}`);
    }
    return components;
}
